// Hand-maintained domain types layered on the generated OpenAPI types.
// `src/lib/api-types.ts` is generated by `npm run types` (make types) from the
// backend's /openapi.json; never hand-edit it. The generated schemas type enums
// as plain strings and JSON payloads as records, so this file narrows them to
// the enums and payload shapes in docs/02-data-model.md and docs/03-api-contracts.md.
// If the backend schema changes, `npm run typecheck` fails here first.

import type { components } from "./api-types";

type S = components["schemas"];
/** Replace the keys of T that O redefines. */
type Narrow<T, O> = Omit<T, keyof O> & O;
export type Lang = "en" | "es";
export type Pace = "standard" | "extra_time";
export type Hearing = "typical" | "hard_of_hearing";
export type Role = "coordinator" | "investigator" | "sponsor";

export type CheckInStatus =
  | "scheduled"
  | "dialing"
  | "in_progress"
  | "completed"
  | "no_answer"
  | "failed"
  | "cancelled";

/** `due` only appears in GET /api/checkins?date= for patients without a check-in yet. */
export type TodayStatus = CheckInStatus | "due";

export type Channel = "phone" | "phone_inbound" | "web" | "replay";
export type Speaker = "patient" | "caregiver";
export type Reporter = "patient" | "caregiver";
export type AnswerSource = "live_tool" | "post_call_extraction" | "replay";

export type EscalationLevel = "emergency" | "urgent" | "callback";
export type FindingEscalationLevel = EscalationLevel | "none";
export type EscalationStatus = "open" | "acknowledged" | "resolved";
export type EscalationReason =
  | "live_rule"
  | "agent_report"
  | "post_call_safety_net"
  | "patient_request"
  | "medical_question"
  | "care_visit";
export type AckMethod = "push_button" | "phone_keypress" | "dashboard";
export type PageChannel = "ntfy" | "twilio_voice" | "console";

export type DraftKind = "AE" | "CM" | "NURSE_TASK";
export type DraftStatus = "draft" | "confirmed" | "rejected";

export type SeriousnessCriterion =
  | "death"
  | "life_threatening"
  | "hospitalization"
  | "disability"
  | "congenital_anomaly"
  | "important_medical_event";

export type Relatedness =
  | "not_related"
  | "unlikely_related"
  | "possibly_related"
  | "probably_related"
  | "related";

export type SaeStatus = "draft" | "signed" | "sent";

// ---------------------------------------------------------------- reference

export type Health = S["Health"];
export type Study = S["StudyOut"];

export type PlanItem = Narrow<S["PlanItemOut"], { text: Partial<Record<Lang, string>> }>;
export type PlanRedFlag = Narrow<S["PlanRedFlagOut"], { level: EscalationLevel }>;

export interface SourceCitation {
  text: string;
  page: number;
}

export type Plan = Narrow<
  S["PlanOut"],
  {
    status: "draft" | "approved" | "superseded";
    items: PlanItem[];
    red_flags: PlanRedFlag[];
    source_citations: Partial<SourceCitation>[];
  }
>;

// ---------------------------------------------------------------- patients

export type NextDue = S["NextDue"];

export type PatientSummary = Narrow<
  S["PatientSummary"],
  { language: Lang; pace: Pace; hearing: Hearing; last_checkin_status?: CheckInStatus | null }
>;

/** Small patient object embedded in check-ins, escalations, drafts and reports. */
export type PatientRef = Narrow<S["PatientBrief"], { language: Lang; pace: Pace }>;

export type TimelinePoint = S["TimelinePoint"];
export type TermTimeline = S["TermTimeline"];

// ---------------------------------------------------------------- check-ins

export type InterviewState = S["InterviewStateOut"];

export type CheckIn = Narrow<
  S["CheckInOut"],
  { status: CheckInStatus; channel: Channel; language: Lang; pace: Pace; speaker: Speaker | null }
>;

export type PatientDetail = Narrow<
  S["PatientDetail"],
  {
    language: Lang;
    pace: Pace;
    hearing: Hearing;
    last_checkin_status?: CheckInStatus | null;
    baseline: Record<string, number | string | null>;
    checkins: CheckIn[];
  }
>;

/** Row of GET /api/checkins?date=. `id` is null for `status: "due"` rows. */
export type TodayRow = Narrow<
  S["CheckInListItem"],
  { status: TodayStatus; channel: Channel | null; patient: PatientSummary }
>;

export type Answer = Narrow<S["AnswerOut"], { quote_lang: Lang; reporter: Reporter; source: AnswerSource }>;

export type Finding = Narrow<
  S["FindingOut"],
  {
    grade_basis: "rule" | "needs_clinician";
    inputs: Record<string, string | number | boolean | null>;
    escalation_level: FindingEscalationLevel;
  }
>;

export type Escalation = Narrow<
  S["EscalationOut"],
  {
    level: EscalationLevel;
    status: EscalationStatus;
    reason: EscalationReason;
    patient_language: Lang;
    page_channel: PageChannel | null;
    ack_method: AckMethod | null;
    patient?: PatientRef | null;
  }
>;

export type TranscriptTurn = Narrow<S["TranscriptTurn"], { role: "agent" | "user"; lang?: Lang | null }>;

export type CheckInDetail = Narrow<
  S["CheckInDetail"],
  {
    checkin: CheckIn;
    patient: PatientRef;
    answers: Answer[];
    findings: Finding[];
    escalations: Escalation[];
    drafts: DraftEntry[];
    transcript: TranscriptTurn[];
  }
>;

export type WebSession = S["WebSession"];

export type CreateCheckInRequest = S["CreateCheckInIn"];

export type CreateCheckInResponse = Narrow<S["CreateCheckInOut"], { checkin: CheckIn }>;

// ---------------------------------------------------------------- drafts

export type Evidence = Narrow<S["EvidenceOut"], { quote_lang: Lang; source: AnswerSource }>;

export interface AnswerRef {
  item_code: string;
  option_code?: string | null;
  numeric_value?: number | null;
}

export interface AEPayload {
  term: string;
  verbatim_en: string;
  onset_date: string | null;
  ongoing: boolean;
  provisional_grade: number | null;
  grade_basis: "rule" | "needs_clinician";
  rule_id: string | null;
  rule_text: string | null;
  answers: AnswerRef[];
  escalation_id: string | null;
}

export interface CMPayload {
  medication_name: string;
  /** The agent's description when post-call extraction normalized medication_name. */
  as_reported_en?: string | null;
  otc: boolean;
  indication_en: string | null;
  start_date: string | null;
  dose_text: string | null;
}

export type NurseTaskCategory =
  | "medical_question"
  | "wants_person"
  | "distress"
  | "other"
  | "care_visit"
  | "anything_else";

export interface NurseTaskPayload {
  category: NurseTaskCategory | string;
  text_en: string;
  detail?: string | null;
}

export interface InvestigatorDecision {
  is_serious: boolean;
  seriousness_criteria: SeriousnessCriterion[];
  relatedness: Relatedness | null;
  signed_by: string | null;
  signed_at: string | null;
}

type DraftBase = Narrow<
  Omit<S["DraftOut"], "kind" | "payload">,
  {
    status: DraftStatus;
    evidence: Evidence[];
    investigator: InvestigatorDecision | null;
    patient?: PatientRef | null;
  }
>;

export type DraftEntry =
  | (DraftBase & { kind: "AE"; payload: AEPayload })
  | (DraftBase & { kind: "CM"; payload: CMPayload })
  | (DraftBase & { kind: "NURSE_TASK"; payload: NurseTaskPayload });

export type InvestigatorRequest = S["InvestigatorIn"];

export type InvestigatorResponse = Narrow<S["InvestigatorOut"], { draft: DraftEntry; sae_report?: SAEReport | null }>;

// ---------------------------------------------------------------- SAE

export interface CiomsPayload {
  report_type: string;
  date_of_report: string;
  study: { nct_id: string; site_id: string; sponsor_study_number?: string };
  patient: {
    subject_id: string;
    initials?: string;
    age?: number;
    sex?: string;
    country?: string;
  };
  reaction: {
    term: string;
    onset_date: string | null;
    provisional_ctcae_grade: number | null;
    ctcae_version: string;
    description: string;
    outcome: string;
  };
  seriousness: SeriousnessCriterion[];
  suspect_product: {
    description: string;
    route: string;
    last_dose_date: string | null;
  };
  concomitant: { medication: string; start_date: string | null; otc: boolean }[];
  causality: { assessed_by: string; result: Relatedness | null };
  reporter: { name: string; role: string; site: string };
  aware_at: string;
  due_at: string;
  narrative?: string;
  narrative_ai_draft_used?: boolean;
}

export type SAEReport = Narrow<S["SAEOut"], { status: SaeStatus; payload: CiomsPayload; patient?: PatientRef | null }>;

export type ValidCaseChecks = S["ValidCaseChecks"];

export type SponsorInboxItem = Narrow<
  S["SponsorInboxItem"],
  { seriousness_criteria: SeriousnessCriterion[]; relatedness: Relatedness | null }
>;

// ---------------------------------------------------------------- audit

export type AuditEvent = S["AuditOut"];


// ---------------------------------------------------------------- eval + validation
// GET /api/eval/latest and /api/validation/latest return free-form JSON
// (eval/results/latest.json, validation/summary.json); shapes from docs/07.

/** Clopper-Pearson exact two-sided 95% interval `[lo, hi]` (docs/03 §6.11). */
export type Ci95 = [number, number];

/**
 * One block of `overall`, `by_language.*` or `by_pace.*`. Every proportion metric `<m>` has a sibling
 * `<m>_ci95` (null when its denominator is 0, and then the metric is null too); counts have no interval.
 */
export interface EvalMetrics {
  n?: number;
  passed?: number;
  passed_ci95?: Ci95 | null;
  red_flag_cases?: number;
  red_flag_caught?: number;
  red_flag_recall?: number | null;
  red_flag_recall_ci95?: Ci95 | null;
  escalation_accuracy?: number | null;
  false_alarms?: number;
  ae_recall?: number | null;
  ae_precision?: number | null;
  grade_agreement?: number | null;
  cm_recall?: number | null;
  disclosure?: number | null;
  advice_refusals?: number | null;
  no_advice_flags?: number;
  approved_wording?: number | null;
  readback_extra_time?: number | null;
  interruptions_per_call?: number;
  [key: string]: number | Ci95 | null | undefined;
}

export interface EvalPersona {
  id: string;
  pass: boolean;
  expected_level: FindingEscalationLevel;
  actual_level: FindingEscalationLevel;
  notes?: string;
  language?: Lang;
  pace?: Pace;
  title?: string;
  transcript?: string;
}

export interface KnownMiss {
  persona: string;
  what: string;
  why: string;
  planned_fix: string;
}

export interface EvalLatest {
  run_at: string;
  commit: string;
  mode: string;
  /** a single model name (older runs) or the per-role models used */
  model?: string | { agent?: string; patient?: string; judge?: string; postcall_provider?: string };
  not_run?: string[];
  overall: EvalMetrics;
  by_language: Partial<Record<Lang, EvalMetrics>>;
  by_pace: Partial<Record<Pace, EvalMetrics>>;
  /** consecutive red-flag catches needed to show recall >= p at one-sided 95% confidence, keyed by p ("0.95") */
  zero_failure_n?: Record<string, number>;
  personas: EvalPersona[];
  known_misses: KnownMiss[];
}

/** One real browser call against the deployed live backend (eval/results/voice_checks.json, V10). */
export interface VoiceCheckCall {
  variant?: string | null;
  conversation_id?: string | null;
  checkin_id?: string | null;
  scenario?: string | null;
  disclosure_first_turn?: boolean | null;
  red_flag_expected?: boolean | null;
  paged?: boolean | null;
  utterance_to_page_s?: number | null;
  page_to_ack_s?: number | null;
  grade?: number | null;
  rule_id?: string | null;
  /** "pending" (or `pending: true`) marks a placeholder row prepared before the call: not a result */
  status?: string | null;
  pending?: boolean | null;
}

/** GET /api/eval/voice-checks (docs/03 §6.11): the file plus `data_origin: "MEASURED"`; 404 `no_voice_checks` when absent. */
export interface VoiceChecks {
  run_at?: string | null;
  backend?: string | null;
  agent_llm?: string | null;
  data_origin: "MEASURED";
  calls?: VoiceCheckCall[];
}

export interface ValidationRow {
  id: string;
  title?: string;
  risk?: string;
  text?: string;
  tests?: string[];
  passed?: number;
  total?: number;
  /** e.g. "PASS", "FAIL", "NO TEST" */
  status?: string;
}

/** validation/summary.json as written by validation/build_traceability.py. All fields optional. */
export interface ValidationSummary {
  generated_at?: string;
  commit?: string;
  requirements?: number;
  requirements_passing?: number;
  tests_total?: number;
  tests_passed?: number;
  tests_linked?: number;
  pytest_exit_code?: number;
  rows?: ValidationRow[];
}

// ---------------------------------------------------------------- demo

export type DemoScenario = S["ScenarioOut"];
/** `POST /api/demo/replay/{id}?speed=` playback multiplier (docs/03 §6.2). */
export type ReplaySpeed = S["ReplaySpeed"];
export type ReplayResponse = S["ReplayOut"];
export type OkResponse = S["OkOut"];
